<?php
namespace App\Http\Controllers;
use App\Models\{AuditLog,Photo,ServiceOrder};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use Intervention\Image\Laravel\Facades\Image;
class PhotoController extends Controller{public const STAGES=['Entrada','Desmontagem','Bobinagem','Montagem','Testes','Finalização'];public function store(Request $request,ServiceOrder $os){abort_unless($request->user()?->canTakePhotos(),403);$data=$request->validate(['stage'=>'required|in:Entrada,Desmontagem,Bobinagem,Montagem,Testes,Finalização','photos'=>'required|array|min:1|max:30','photos.*'=>'required|image|mimes:jpg,jpeg,png,webp|max:51200']);foreach($request->file('photos',[]) as $file){$now=now();$stage=$data['stage'];$slug=Str::upper(Str::slug($stage,'_'));$ext=strtolower($file->getClientOriginalExtension()?:'jpg');$seq=$os->photos()->withTrashed()->where('stage',$stage)->count()+1;do{$filename='OS'.$os->number.'_'.$slug.'_'.$now->format('Y-m-d_H-i-s').'_'.$seq.'.'.$ext;$original="photos/{$os->number}/$slug/$filename";$seq++;}while(Storage::disk('local')->exists($original));$thumb="thumbs/{$os->number}/$slug/$filename.jpg";Storage::disk('local')->putFileAs(dirname($original),$file,basename($original));$image=Image::read($file->getRealPath())->scaleDown(width:1400);Storage::disk('local')->put($thumb,(string)$image->toJpeg(84));$photo=Photo::create(['service_order_id'=>$os->id,'user_id'=>$request->user()->id,'stage'=>$stage,'original_path'=>$original,'thumbnail_path'=>$thumb,'original_name'=>$file->getClientOriginalName(),'mime_type'=>$file->getMimeType(),'size'=>$file->getSize(),'captured_at'=>$now]);AuditLog::create(['user_id'=>$request->user()->id,'action'=>'photo.added','service_order_id'=>$os->id,'photo_id'=>$photo->id,'metadata'=>['stage'=>$stage,'filename'=>$filename]]);}return back()->with('ok','Fotos salvas.');}public function destroy(Request $request,Photo $photo){abort_unless($request->user()?->canDeletePhotos(),403);AuditLog::create(['user_id'=>$request->user()->id,'action'=>'photo.deleted','service_order_id'=>$photo->service_order_id,'photo_id'=>$photo->id,'metadata'=>['stage'=>$photo->stage,'filename'=>basename($photo->original_path)]]);Storage::disk('local')->delete([$photo->original_path,$photo->thumbnail_path]);$photo->delete();return back()->with('ok','Foto excluída e registrada no histórico.');}public function file(Request $request,Photo $photo){abort_unless($request->user(),401);$path=$request->boolean('thumb')?$photo->thumbnail_path:$photo->original_path;abort_unless(Storage::disk('local')->exists($path),404);return response()->file(Storage::disk('local')->path($path),['Cache-Control'=>'private, max-age=86400']);}public function downloadStage(Request $request,ServiceOrder $os){abort_unless($request->user()?->canDownload(),403);$stage=$request->string('stage')->toString();abort_unless(in_array($stage,self::STAGES,true),422);return $this->makeZip($os,$os->photos()->where('stage',$stage)->get(),$stage);}public function downloadAll(Request $request,ServiceOrder $os){abort_unless($request->user()?->canDownload(),403);return $this->makeZip($os,$os->photos()->get(),'todas');}private function makeZip(ServiceOrder $os,$photos,string $label){abort_if($photos->isEmpty(),404,'Nenhuma foto encontrada.');$zipPath=storage_path('app/pservice_os_'.$os->id.'_'.Str::uuid().'.zip');$zip=new \ZipArchive();abort_unless($zip->open($zipPath,\ZipArchive::CREATE|\ZipArchive::OVERWRITE)===true,500);foreach($photos as $photo)if(Storage::disk('local')->exists($photo->original_path))$zip->addFile(Storage::disk('local')->path($photo->original_path),'OS'.$os->number.'/'.Str::upper(Str::slug($photo->stage,'_')).'/'.basename($photo->original_path));$zip->close();return response()->download($zipPath,'OS'.$os->number.'_'.Str::slug($label).'.zip')->deleteFileAfterSend(true);}}
